// Standard C Dynamic Memory Allocation
// (The consumer's view of the heap)
int* buffer;
size_t required_bytes = sizeof(int) * 100;

buffer = (int*)malloc(required_bytes);

if (buffer != NULL) {
    buffer[0] = 42;
}

// Releases memory back to the heap manager
free(buffer);

// Block Header Structure (Internal Heap Manager View)
typedef struct BlockHeader {
    size_t size;         // Total size (incl. header/footer)
    bool allocated;      // true if in use, false if free
    struct BlockHeader* next; // Pointer in the free list
} BlockHeader;

#define BLOCK_SIZE(b) (b->size)

// Coalescing Logic: Merge Current and Next if Next is Free
void attempt_coalesce(BlockHeader* current) {
    BlockHeader* next = GET_NEXT_BLOCK(current);

    if (!current->allocated && !next->allocated) {
        // Merge: Add next block's size to current block
        current->size += next->size;
        // Update the boundary tag of the merged block
        UPDATE_FOOTER(current);
        // Remove 'next' from the free list
        REMOVE_FROM_FREE_LIST(next);
    }
}
